SELECT CASE WHEN departments.budget >= 3581000 THEN 'high' WHEN departments.budget >= 1593000 THEN 'mid' ELSE 'low' END AS budget_bucket, COUNT(DISTINCT employees.salary) AS unique_depts FROM employees JOIN departments ON employees.dept_id = departments.id WHERE employees.salary BETWEEN 92000 AND 136000 GROUP BY CASE WHEN departments.budget >= 3581000 THEN 'high' WHEN departments.budget >= 1593000 THEN 'mid' ELSE 'low' END ORDER BY budget_bucket;
